head.script:
scwin.overClick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    var ev = document.createEvent("MouseEvents");
    ev.initEvent("mouseover", true, true);
    el.dispatchEvent(ev);
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 0. column의 inputType="button"이고 title="buttonExplain"로 설정한다. 1. 샘플파일을 실행 후 name3항목의 필드에 마우스를 올려놓는다.
    //Set column inputType = "button" and title = "buttonExplain" . 1. After running the sample file, mouse over the field of the name3 item.
    //Verify step 1. The value of buttonExplain is shown in tooltip format (inputtype = button also shows title attribute value).
    WebSquare.wUnit.addCommand("set", "scwin.overClick($p.id+'wq_uuid_3_cell_0_2')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'wq_uuid_3_cell_0_2').getElementsByTagName('button')[0].getAttribute('title') == 'buttonExplain'", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    dataList1.insertRow();
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 08-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
